"use client";

import {useEffect,useMemo,useState,type ComponentProps,type FormEvent,type ReactNode} from "react";
import {useMutation,useQuery,useQueryClient} from "@tanstack/react-query";
import {AlertTriangle,BarChart3,BookOpen,Building2,CalendarRange,CheckCircle2,ChevronRight,FilePenLine,Landmark,Link2,Loader2,Plus,ReceiptText,RefreshCw,Settings2,TableProperties,Trash2} from "lucide-react";
import {toast} from "sonner";
import {accountingApi,type AccountingCostCenter,type AccountingCostCenterAssignment,type BankAccount} from "@/services/api/accounting";
import {payablesApi} from "@/services/api/payables";
import {receivablesApi} from "@/services/api/receivables";
import {inventoryApi} from "@/services/api/inventory";
import {PartySelect} from "@/components/parties/party-role-select";
import {AccountingDocumentDialog} from "@/components/accounting/accounting-document-dialog";
